from django.conf import settings
from django.contrib.auth.backends import ModelBackend
from django.core.exceptions import ImproperlyConfigured
from django.db.models import get_model

class UserModelBackend(ModelBackend):
	def authenticate(self, username=None, password=None):
		try:
			user = self.user_class.objects.get(username=username)
			if user.check_password(password):
				return user
		except self.user_class.DoesNotExist:
			pass

		# If we got here, it means we couldn't find a matching user
		# in our custom User model.  So, let's go check the vanilla
		# Django user table.  If we find a match there, we can 
		# create a new custom user, clone all the information over,
		# and then delete the vanilla user.

		try:
			user = self.normal_user_class.objects.get(username=username)
			if user.check_password(password):
				self.cloneOver(user)
				user.delete()
				return self.user_class.objects.get(username=username)
		except self.normal_user_class.DoesNotExist:
			pass

		return None

	def get_user(self, user_id):
		try:
			return self.user_class.objects.get(pk=user_id)
		except self.user_class.DoesNotExist:
			return None

	def cloneOver(self, vanillaUser):
		newUser = self.user_class.objects.create(username=vanillaUser.username)
		newUser.set_password(vanillaUser.password)
		newUser.first_name = vanillaUser.first_name
		newUser.last_name = vanillaUser.last_name
		newUser.email = vanillaUser.email
		newUser.is_staff = vanillaUser.is_staff
		newUser.is_active = vanillaUser.is_active
		newUser.save()

	@property
	def user_class(self):
		if not hasattr(self, '_user_class'):
			self._user_class = get_model(*settings.CUSTOM_USER_MODEL.split('.', 2))
			if not self._user_class:
				raise ImproperlyConfigured('Could not get custom user model')
		return self._user_class

	@property
	def normal_user_class(self):
		if not hasattr(self, '_normal_user_class'):
			self._normal_user_class = get_model('auth', 'user')
		return self._normal_user_class

